import { ApiProperty, ApiPropertyOptional, PartialType } from '@nestjs/swagger';
import { Transform, Type } from 'class-transformer';
import {
  IsBoolean,
  IsIn,
  IsNotEmpty,
  IsOptional,
  IsString,
  MaxLength,
  ValidateIf,
} from 'class-validator';
import {
  PaymentGatewayType,
  PaymentMethod,
} from '../../database/enums/enums';

/**
 * `slug` is deliberately absent: it is generated by the backend from `name` and
 * is the value stored on `Payment.method`. Anything a client sends for it is
 * stripped by the global ValidationPipe whitelist.
 *
 * Manual-only fields are validated conditionally on `type` + `isManual`:
 *  - MFS  + manual → accountName, accountNumber
 *  - Bank + manual → accountName, accountNumber, bankName, branchName
 *  - automated     → provider (the PaymentMethod the callback settles)
 */
export class CreatePaymentGatewayDto {
  @ApiProperty({ example: 'bKash' })
  @IsString()
  @IsNotEmpty()
  @MaxLength(250)
  name: string;

  @ApiProperty({ example: 'বিকাশ' })
  @IsString()
  @IsNotEmpty()
  @MaxLength(250)
  nameBN: string;

  @ApiPropertyOptional({ enum: PaymentGatewayType, default: PaymentGatewayType.MFS })
  @IsIn(Object.values(PaymentGatewayType), {
    message: 'type must be mfs or bank',
  })
  type: PaymentGatewayType;

  @ApiProperty({ example: true, description: 'Manual = customer pays and submits proof.' })
  @IsBoolean()
  @Type(() => Boolean)
  isManual: boolean;

  @ApiPropertyOptional({ default: true })
  @IsOptional()
  @IsBoolean()
  @Type(() => Boolean)
  isActive?: boolean;

  @ApiPropertyOptional({
    enum: PaymentMethod,
    description:
      'Required when isManual = false — the existing automated method this gateway settles through.',
  })
  @ValidateIf((dto: CreatePaymentGatewayDto) => dto.isManual === false)
  @IsIn(Object.values(PaymentMethod), {
    message: 'provider must be bkash, nagad or card for an automated gateway',
  })
  provider?: PaymentMethod;

  @ApiPropertyOptional({
    example: '<p>Send the payment to <strong>01700000000</strong>.</p>',
    description: 'Rich text (HTML). Sanitized server-side before it is stored.',
  })
  @IsOptional()
  @IsString()
  @MaxLength(5000)
  @Transform(({ value }) => (typeof value === 'string' ? value : undefined))
  description?: string;

  @ApiPropertyOptional({ description: 'URL returned by the gateway icon upload.' })
  @IsOptional()
  @IsString()
  @MaxLength(1000)
  iconUrl?: string;

  @ApiPropertyOptional({ description: 'Storage path for cleanup (upload response).' })
  @IsOptional()
  @IsString()
  @MaxLength(1000)
  iconPath?: string;

  // ---- manual MFS ----

  @ApiPropertyOptional({ example: 'Jabaib Fashion Ltd.' })
  @ValidateIf((dto: CreatePaymentGatewayDto) => dto.isManual === true)
  @IsString()
  @IsNotEmpty({ message: 'accountName is required for a manual payment gateway' })
  @MaxLength(250)
  accountName?: string;

  @ApiPropertyOptional({ example: '01700000000' })
  @ValidateIf((dto: CreatePaymentGatewayDto) => dto.isManual === true)
  @IsString()
  @IsNotEmpty({ message: 'accountNumber is required for a manual payment gateway' })
  @MaxLength(100)
  accountNumber?: string;

  // ---- manual Bank (extra fields) ----

  @ApiPropertyOptional({ example: 'Dutch-Bangla Bank' })
  @ValidateIf(
    (dto: CreatePaymentGatewayDto) =>
      dto.isManual === true && dto.type === PaymentGatewayType.BANK,
  )
  @IsString()
  @IsNotEmpty({ message: 'bankName is required for a manual bank gateway' })
  @MaxLength(250)
  bankName?: string;

  @ApiPropertyOptional({ example: 'Dhanmondi Branch' })
  @ValidateIf(
    (dto: CreatePaymentGatewayDto) =>
      dto.isManual === true && dto.type === PaymentGatewayType.BANK,
  )
  @IsString()
  @IsNotEmpty({ message: 'branchName is required for a manual bank gateway' })
  @MaxLength(250)
  branchName?: string;
}
/**
 * PATCH. `PartialType` marks every field optional, so the conditional rules on
 * `CreatePaymentGatewayDto` only fire for keys the payload actually contains.
 * The service re-checks the *merged* row (an admin switching type mfs → bank
 * must end up with bank details), which a per-field rule cannot see.
 */
export class UpdatePaymentGatewayDto extends PartialType(CreatePaymentGatewayDto) {}
